      "check": {
        "prompt_fil": "Sumasagot ang kapitbahay para kay Liza. Ano ang unang gagawin ni Gibs?",
        "prompt_en": "A neighbor answers for Liza. What should Gibs do first?",
        "options": [
          {
            "fil": "Ituloy ang form gamit ang sagot ng kapitbahay.",
            "en": "Complete the form using the neighbor’s answers."
